// 🎤 Inglés oral (8°, convocatoria): la prueba es una entrevista oral. Cinco temas del temario, práctica con
// preguntas que se oyen en inglés y se contestan en voz alta (más ejercicios que se corrigen solos) y dos
// simulacros de entrevista. La forma de cada pieza está en js/c8/revisar.js.

/** Pregunta oral: `p` se lee en voz alta en inglés; cada criterio de `guia` vale 1 punto. */
const oral = (p, seg, guia, modelo) => ({ t: "oral", p, seg, guia, modelo });

// Criterios que se repiten en las guías de las preguntas orales.
const COMPLETA = "Contestó con oración completa: sujeto + verbo (no una sola palabra ni un «yes» solo).";
const RAZON = "Dio al menos un detalle o una razón (because…, for example…, also…).";
const FLUIDA = "Se le entendió: sin pausas largas, sin leer y sin pasarse al español.";
const PRESENTE = "Usó bien el presente simple (con he/she el verbo lleva -s: «she works», «he plays»).";
const PASADO = "Usó bien el pasado simple (went, saw, was…; nada de «did + verbo en pasado»).";
const PRESENTACION = [
  "Saludó y dijo de qué iba a hablar (Good morning… Today I am going to recommend…).",
  "Recomendó al menos dos lugares concretos, cada uno con su razón (because…).",
  "Usó al menos cuatro conectores distintos (First, Also, However, So, Finally / In conclusion…).",
  "Usó bien al menos un comparativo o superlativo (cheaper than, the best, the most convenient).",
  "Cerró con una conclusión y «Thank you for listening».",
  "Habló entre 1 y 2 minutos, sin leer, y se le entendió.",
];

